def collatz_orbit(n: int) -> list[int]:
    orbit = [n]
    while n != 1 and len(orbit) < 10**6:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        orbit.append(n)
    return orbit

def verify_parity_balance(n: int) -> bool:
    odd, total = 0, 0
    current = n
    while current != 1:
        if current % 2 == 1:
            odd += 1
        current = current // 2 if current % 2 == 0 else 3 * current + 1
        total += 1
    return 3 * odd < 2 * total

def gcs_step(n: int, m: int, a: list[int], b: list[int]) -> int:
    r = n % m
    return (a[r] * n + b[r]) // m
